// ── E2E P2P capability areas (Oracle only) ────────────────────────
const E2E_AREAS = {
  'Supplier Master Data': new Set([
    'maintain supplier news content','maintain supplier numbering setup','maintain supplier',
    'maintain supplier address','maintain supplier attachment','maintain supplier business classification',
    'maintain supplier contact','maintain supplier contact change request','maintain supplier contact user account',
    'maintain supplier income tax','maintain supplier payment','maintain supplier products and services categories',
    'maintain supplier transaction tax','maintain supplier in crm import export management',
    'maintain supplier business relationship','maintain supplier contact user account as supplier',
    'maintain supplier contact as supplier','maintain supplier site','maintain supplier site assignment',
    'maintain supplier site b2b communication information','maintain supplier site invoicing information',
    'maintain supplier site purchasing information','maintain supplier site receiving information'
  ]),
  'Procurement (PR/PO)': new Set([
    'manage requisition','manage requisition by rest service',
    'edit purchase order-matched supplier portal invoices','cancel purchase order','change purchase order',
    'change purchase order line negotiated indicator','manage purchase order by web service',
    'retroactively price purchase order','manage procurement agent by rest service','manage procurement agent',
    'maintain purchasing configurations'
  ]),
  'Invoice Processing & Overrides': new Set([
    'cancel payables invoice','delete payables invoice','edit payables invoice',
    'hold invoice from approval task flow','force approve payables invoice','validate payables invoice',
    'approve payables invoice','force approve invoice','release hold on payables invoice',
    'manage payables invoices'
  ]),
  'AP Configuration': new Set(['maintain payables configurations']),
  'Workflow Maintenance': new Set([
    'edit approval rules in oracle bpm worklist','run bpm workflow reports',
    'migrate pending approvals to bpm workflow'
  ]),
  'Payment Processing': new Set([
    'manage payables payments','assign payment process attributes to document payable',
    'edit payables payment','manage payables payment process request',
    'process payables payment process request','stop payables payment','void payables payment',
    'create payables payment','create payment','process payables payment process request template'
  ]),
  'Period Close': new Set([
    'manage period close activities','submit subledger period close exceptions report',
    'submit period close exceptions report','run close period program','manage accounting period status'
  ]),
  'Bank Reconciliation': new Set([
    'import bank statement reconciliation external transaction','manage bank statement autoreconciliation exception',
    'manage bank statement and reconciliation activities','mark bank statement reconciliation reviewed',
    'submit autoreconciliation','manage bank statement automatic reconciliation matching rule set',
    'manage bank statement reconciliation matching rule','manage bank statement reconciliation tolerance',
    'create collections'
  ])
};
const E2E_THRESHOLD = 8;

function matchSideDetail(names, privSet, mode){
  if(!names || !names.length) return null;
  const nameSet = new Set(names.map(n => n.toLowerCase().trim()));
  const matched = [];
  for(const p of privSet){
    if(nameSet.has(String(p).toLowerCase().trim())) matched.push(p);
  }
  const n = names.length;
  const threshold = (mode === 'majority') ? (n <= 4 ? 1 : Math.ceil(n * 0.4)) : 1;
  return matched.length >= threshold ? matched : null;
}

// ═══════════════════════════════════════════════════════════════
// ORACLE ENGINE
// Input: userRoles {username: [roleName,...]}, rolePrivs {roleName: [privilegeName,...]}
// ═══════════════════════════════════════════════════════════════
function runOracleServer(userRoles, rolePrivs){
  const rolePrivSets = {};
  for(const [role, privs] of Object.entries(rolePrivs)) rolePrivSets[role] = new Set(privs.map(p=>String(p).toLowerCase().trim()));

  const userFindings = [];
  for(const [u, roles] of Object.entries(userRoles)){
    const privToRoles = {};
    for(const role of roles){
      for(const p of (rolePrivSets[role] || new Set())){
        if(!privToRoles[p]) privToRoles[p] = [];
        privToRoles[p].push(role);
      }
    }
    const privSet = new Set(Object.keys(privToRoles));
    for(const c of ORACLE_CONFLICTS){
      const matchA = matchSideDetail(c.sideA, privSet, c.modeA || 'any');
      const matchB = matchSideDetail(c.sideB, privSet, c.modeB || 'any');
      if(matchA && matchB){
        const rolesA = [...new Set(matchA.flatMap(p=>privToRoles[p]||[]))];
        const rolesB = [...new Set(matchB.flatMap(p=>privToRoles[p]||[]))];
        userFindings.push({ type:'user', conflict:c, user:u, allRoles:roles, rolesA, rolesB, privA:matchA, privB:matchB });
      }
    }
  }

  const roleFindings = [];
  for(const [role, privSet] of Object.entries(rolePrivSets)){
    for(const c of ORACLE_CONFLICTS){
      const matchA = matchSideDetail(c.sideA, privSet, c.modeA || 'any');
      const matchB = matchSideDetail(c.sideB, privSet, c.modeB || 'any');
      if(matchA && matchB){
        const usersWithRole = Object.entries(userRoles).filter(([u,roles])=>roles.includes(role)).map(([u])=>u);
        roleFindings.push({ type:'role', conflict:c, role, usersWithRole, privA:matchA, privB:matchB });
      }
    }
  }

  const e2eFindings = [];
  for(const [u, roles] of Object.entries(userRoles)){
    const allPrivs = new Set();
    for(const r of roles) for(const p of (rolePrivSets[r]||new Set())) allPrivs.add(p);
    const touchedAreas = []; const areaMatches = {};
    for(const [area, nameSet] of Object.entries(E2E_AREAS)){
      const hits = [...allPrivs].filter(p=>nameSet.has(p));
      if(hits.length){ touchedAreas.push(area); areaMatches[area] = hits; }
    }
    if(touchedAreas.length >= E2E_THRESHOLD){
      e2eFindings.push({ user:u, allRoles:roles, areasCount:touchedAreas.length, areas:touchedAreas, areaMatches });
    }
  }

  return { results:userFindings, roleResults:roleFindings, e2eResults:e2eFindings, totalUsers:Object.keys(userRoles).length };
}


// ═══════════════════════════════════════════════════════════════
// SINGLE-USER QUICK CHECK — spot-check one person's access without a
// full file upload. Reuses ORACLE_CONFLICTS + matchSideDetail exactly
// as the bulk engine does. ROLE_PRIVILEGES is the DAMAC-specific
// built-in Oracle role catalog (3,012 roles) used to resolve a role
// name to its privilege set when the auditor doesn't have a role-
// privilege export handy. Both stay server-side — the client only
// ever receives role display names (for autocomplete) and findings.
// ═══════════════════════════════════════════════════════════════
