function getOracleVocab(){
  return {
    privileges: [...new Set(ORACLE_CONFLICTS.flatMap(r=>[...r.sideA,...r.sideB]))].sort((a,b)=>a.localeCompare(b)),
    roleNames: Object.values(ROLE_PRIVILEGES).map(e=>e.display).sort((a,b)=>a.localeCompare(b))
  };
}

function resolveRolesToPrivileges(roleNames){
  const set = new Set();
  const unresolved = [];
  for(const r of (roleNames||[])){
    const entry = ROLE_PRIVILEGES[String(r).toLowerCase().trim()];
    if(entry) for(const p of entry.privs) set.add(p);
    else unresolved.push(r);
  }
  return { privileges:[...set], unresolved };
}

function runOracleQuickCheck(privArray){
  const privSet = new Set((privArray||[]).map(p=>String(p).trim()).filter(Boolean));
  const findings=[];
  for(const c of ORACLE_CONFLICTS){
    const matchA = matchSideDetail(c.sideA, privSet, c.modeA||'any');
    const matchB = matchSideDetail(c.sideB, privSet, c.modeB||'any');
    if(matchA && matchB) findings.push({conflict:c, privA:matchA, privB:matchB});
  }
  return findings;
}

module.exports = { ORACLE_CONFLICTS, E2E_AREAS, E2E_THRESHOLD, matchSideDetail, runOracleServer, getOracleVocab, resolveRolesToPrivileges, runOracleQuickCheck };
